INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, source, status, subject)
VALUES ('cc36abd9-d6df-5ad2-80fb-b5ddc4093064', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'Biology: K-12 hours by grade band and year', 'The timetable of biology with four grade bands of 3, 3, 3 and 4 years and three hour tiers (lower K-4, middle 5-8, upper 9-12). Hours are placeholders and editable. A plan on this axis counts its content against biology time.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"lower","label":"Lower grades (K-4)","where":{"year":{"range":[1,5],"absolute":true}},"duration":{"low":"PT8H","high":"PT21H"},"note":"Placeholder, scaled from Dustin 2026-10-25: his first range of 15-45 hours, cut by the same ratio as the upper tier."},{"key":"middle","label":"Middle grades (5-8)","where":{"year":{"range":[6,9],"absolute":true}},"duration":{"low":"PT20H","high":"PT38H"},"note":"Placeholder, scaled the same way from the earlier default of 40-80 hours. Adjustable to local conditions."},{"key":"upper","label":"Upper grades (9-12)","where":{"year":{"range":[10,13],"absolute":true}},"duration":{"low":"PT50H","high":"PT70H"},"note":"Placeholder from Dustin 2026-10-25: 50-70 hours a year. His first figure of 100-150 was likely too high."}]}'::jsonb, 'Hours per year, biology: Dustin Eirdosh, 2026-10-25, revised the same day. All placeholders.', 'proposed', 'biology') ON CONFLICT (id) DO NOTHING;
