INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('48591033-d2f9-5204-94ee-30ac48c9dbd3', '7f604bf5-2f90-5f00-9160-30e9265971c4', '30f34f2e-2382-5639-b42c-c60b7fd02427', NULL, NULL, 'The share of social studies teaching time that this space takes is between 10 and 30 percent.', 'placeholder', 'low', 'No source.', 'The true share is unknown. Every derived number carries the range. The same range is used for all four spaces so that they compare on equal hours.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('d5fa59f4-2d4e-5135-857d-4c2d18bc207e', '7f604bf5-2f90-5f00-9160-30e9265971c4', '30f34f2e-2382-5639-b42c-c60b7fd02427', NULL, NULL, 'Social studies teaching is spread evenly through each year, so the last fifth of the year holds a fifth of its time.', 'derived', 'low', 'Design note 2026-10-25, section 5.4.', 'Used to turn a position in the year into hours.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('9f5a938c-5c62-5edb-8ff0-734218cddac1', '7f604bf5-2f90-5f00-9160-30e9265971c4', '30f34f2e-2382-5639-b42c-c60b7fd02427', NULL, NULL, 'Within a grade band, every stage takes an equal part of the band''s time for this space.', 'derived', 'low', 'Design note 2026-10-25, section 5.5.', 'A starting rule. Stages differ in size, so equal parts are an approximation.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('8799eec2-31a0-5971-91e9-cf4a20ed1279', '7f604bf5-2f90-5f00-9160-30e9265971c4', '30f34f2e-2382-5639-b42c-c60b7fd02427', NULL, NULL, 'A topic gives 15 percent of its time to its reinforcing concepts as threaded time. Its primary concepts share the rest equally.', 'placeholder', 'low', 'No source.', 'Concept time is derived from topic time. The split is an accounting rule and makes no claim about learning.', '{"reinforcing_share":0.15}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('4a88cc9a-707a-5020-927d-5e08e04c8ca9', '7f604bf5-2f90-5f00-9160-30e9265971c4', '4fdaa457-359f-5d46-ab15-9aa93b184c7e', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the space''s time as a thread.', 'placeholder', 'low', 'No source.', 'That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('8e97949a-6a11-5a52-8fca-7e898fbf25d3', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'cea9dd59-41e3-5030-8e64-8ddbb0d17f16', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order. Stages with no dependency between them are ordered by strand and then by id.', 'derived', 'low', 'Design note 2026-10-25, section 5.11.', 'The links come from this space''s own prerequisite claims, authored for its domain. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('9d60d92e-f96e-5d29-be03-712f530c2ce6', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'f29288c7-6133-54a5-8a9c-c0a1370e921b', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little. The control shows what a violation looks like on this space.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b906b32e-a01d-5994-9ed8-6be6a00d1004', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'dc944bfc-58d4-5b58-98e9-a06240dbc352', NULL, NULL, 'Hypothesis from the design note, to be tested and never a recommendation. Threaded time plus spiral blocks are expected to fit this space best, because participation accumulates through sustained practice and concepts attach to cases that recur.', 'placeholder', 'low', 'Design note 2026-10-25, section 8.1.', 'Hypotheses about the fit between content and delivery pattern are tested by the comparison and are not recommendations.', NULL) ON CONFLICT (id) DO NOTHING;

