INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, source, status, subject)
VALUES ('f2bed012-fc38-5b4e-9434-a97734e2a3f8', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'Biology: K-12 hours by grade band and year', 'The timetable of biology with four grade bands of 3, 3, 3 and 4 years and three hour tiers (lower K-4, middle 5-8, upper 9-12). Hours are placeholders and editable. A plan on this axis counts its content against biology time.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"lower","label":"Lower grades (K-4)","where":{"year":{"range":[1,5],"absolute":true}},"duration":{"low":"PT8H","high":"PT21H"},"note":"Placeholder, scaled from Dustin 2026-10-25: his first range of 15-45 hours, cut by the same ratio as the upper tier."},{"key":"middle","label":"Middle grades (5-8)","where":{"year":{"range":[6,9],"absolute":true}},"duration":{"low":"PT20H","high":"PT38H"},"note":"Placeholder, scaled the same way from the earlier default of 40-80 hours. Adjustable to local conditions."},{"key":"upper","label":"Upper grades (9-12)","where":{"year":{"range":[10,13],"absolute":true}},"duration":{"low":"PT50H","high":"PT70H"},"note":"Placeholder from Dustin 2026-10-25: 50-70 hours a year. His first figure of 100-150 was likely too high."}]}'::jsonb, 'Hours per year, biology: Dustin Eirdosh, 2026-10-25, revised the same day. All placeholders.', 'proposed', 'biology') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('c55cca27-8e02-56ad-9b94-1b4b267ff85f', 'bac697ab-febe-5111-a5bd-f266b8b2d837', NULL, 'f2bed012-fc38-5b4e-9434-a97734e2a3f8', NULL, 'Biology gets 8-21 hours a year in the lower grades, 20-38 in the middle grades and 50-70 in the upper grades.', 'estimate', 'low', 'Dustin Eirdosh, 2026-10-25.', 'Dustin Eirdosh gave 50-70 hours for the upper grades on 2026-10-25 (his first figure of 100-150 was judged too high). The lower and middle figures scale his earlier ranges by the same ratio. No published source yet.', NULL) ON CONFLICT (id) DO NOTHING;
