INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('7d2b2e8f-1c01-5b92-9bca-2afca3eb274c', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '942f655b-0c07-5b02-9135-384dc5c8cc23', NULL, NULL, 'The share of computer science teaching time that this space takes is between 10 and 30 percent.', 'placeholder', 'low', 'No source.', 'The true share is unknown. Every derived number carries the range. The same range is used for all four spaces so that they compare on equal hours.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('e10c3626-7585-5174-8977-c857b9f07855', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '942f655b-0c07-5b02-9135-384dc5c8cc23', NULL, NULL, 'Computer science teaching is spread evenly through each year, so the last fifth of the year holds a fifth of its time.', 'derived', 'low', 'Design note 2026-10-25, section 5.4.', 'Used to turn a position in the year into hours.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('5cd4ca85-63f0-598a-9ada-306cd3598c75', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '942f655b-0c07-5b02-9135-384dc5c8cc23', NULL, NULL, 'Within a grade band, every stage takes an equal part of the band''s time for this space.', 'derived', 'low', 'Design note 2026-10-25, section 5.5.', 'A starting rule. Stages differ in size, so equal parts are an approximation.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('295c38bc-55cd-52fa-b1d2-e7d4bc17c7d3', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '942f655b-0c07-5b02-9135-384dc5c8cc23', NULL, NULL, 'A topic gives 15 percent of its time to its reinforcing concepts as threaded time. Its primary concepts share the rest equally.', 'placeholder', 'low', 'No source.', 'Concept time is derived from topic time. The split is an accounting rule and makes no claim about learning.', '{"reinforcing_share":0.15}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('cef3d4f4-f808-58f9-84bc-12a31b28c346', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '84165522-42be-5326-b89e-15a4d23a0a75', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the space''s time as a thread.', 'placeholder', 'low', 'No source.', 'That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b31b3d8a-1897-5994-81d2-b3b7b719dce5', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '5b30a3da-b1eb-52c0-9c42-6fc70b12c6ba', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order. Stages with no dependency between them are ordered by strand and then by id.', 'derived', 'low', 'Design note 2026-10-25, section 5.11.', 'The links come from this space''s own prerequisite claims, authored for its domain. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('af556ccc-bcb0-56ba-bc57-7d95bf08da48', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '773bdb75-c4a4-55ba-8dc3-2396028ffd01', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little. The control shows what a violation looks like on this space.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('e8b779e2-a9c7-5375-b373-c2c835063f0a', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '5b30a3da-b1eb-52c0-9c42-6fc70b12c6ba', NULL, NULL, 'Hypothesis from the design note, to be tested and never a recommendation. A sequenced plan with blocks for projects is expected to fit this space best, because formal prerequisites fix the order and programming practice needs unbroken time.', 'placeholder', 'low', 'Design note 2026-10-25, section 8.1.', 'Hypotheses about the fit between content and delivery pattern are tested by the comparison and are not recommendations.', NULL) ON CONFLICT (id) DO NOTHING;

